private enum InitializationResult {
    case ok
    case contractVersionMismatch
    case apiChecksumMismatch
}
// Use a global variable to perform the versioning checks. Swift ensures that
// the code inside is only computed once.
private let initializationResult: InitializationResult = {
    // Get the bindings contract version from our ComponentInterface
    let bindings_contract_version = 30
    // Get the scaffolding contract version by calling the into the dylib
    let scaffolding_contract_version = ffi_noel_ffi_uniffi_contract_version()
    if bindings_contract_version != scaffolding_contract_version {
        return InitializationResult.contractVersionMismatch
    }
    if (uniffi_noel_ffi_checksum_method_bytechannel_send() != 52298) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_noel_ffi_checksum_method_bytechannel_close() != 29840) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_noel_ffi_checksum_method_channelopener_open_channel() != 14810) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_noel_ffi_checksum_method_delivery_closed() != 58869) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_noel_ffi_checksum_method_delivery_receive() != 64136) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_noel_ffi_checksum_method_noel_abort() != 31730) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_noel_ffi_checksum_method_noel_new_session() != 38101) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_noel_ffi_checksum_method_noel_panel_action() != 8111) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_noel_ffi_checksum_method_noel_run_plugin_command() != 31159) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_noel_ffi_checksum_method_noel_select() != 53862) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_noel_ffi_checksum_method_noel_send() != 2273) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_noel_ffi_checksum_method_noellistener_on_event() != 64557) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_noel_ffi_checksum_constructor_noel_connect() != 27488) {
        return InitializationResult.apiChecksumMismatch
    }

    uniffiCallbackInitByteChannel()
    uniffiCallbackInitChannelOpener()
    uniffiCallbackInitNoelListener()
    return InitializationResult.ok
}()

// Make the ensure init function public so that other modules which have external type references to
// our types can call it.
public func uniffiEnsureNoelFfiInitialized() {
    switch initializationResult {
    case .ok:
        break
    case .contractVersionMismatch:
        fatalError("UniFFI contract version mismatch: try cleaning and rebuilding your project")
    case .apiChecksumMismatch:
        fatalError("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
}

